<?php
namespace App\Services;
use App\Models\Market; use App\Support\{Countries,Currency}; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\DB;
class MarketService { public function default():?Market{return Cache::remember('market.default',60,fn()=>Market::where('is_active',true)->where('is_default',true)->first()??Market::where('is_active',true)->orderBy('sort_order')->first());} public function current($request):?Market{$code=$request->session()->get('market_code');$m=$code?Market::where('code',$code)->where('is_active',true)->first():null;return $m??$this->default();} public function active(){return Cache::remember('market.active',60,fn()=>Market::where('is_active',true)->orderBy('sort_order')->orderBy('name')->get());} public function select(string $code):?Market{$m=Market::where('code',$code)->where('is_active',true)->first();return $m;} public function save(array $data,?Market $market=null):Market{return DB::transaction(function()use($data,$market){$market=$market??new Market; $market->fill($data); if($market->is_default){Market::whereKey($market->id??0)->update(['is_default'=>false]);} $market->save(); if($market->is_default)Market::where('id','<>',$market->id)->update(['is_default'=>false]); return $market;});} public function clear():void{Cache::forget('market.default');Cache::forget('market.active');} public function currencies():array{return config('marketplace.currency.supported',[]);} public function countries():array{return Countries::supported();} }
